# ===== Plugin =====
class ComponentMetadataServer:
    """Provide component metadata json definitions, such as parameters."""

    def __init__(self, server_component):
        self._lib = _cmavsdk_lib
        self._handle = None
        self._callbacks = []  # Keep references to prevent GC
        # Stream subscriptions, by handle: the trampoline to keep alive and the
        # unsubscribe to call for it. destroy() releases whatever is left. Entries
        # are taken under the lock below, so a handle goes to either destroy() or
        # one unsubscribe, never both. The C call then happens outside the lock,
        # which waits for a running callback -- and a callback may unsubscribe.
        self._subscriptions = {}
        # destroy() can be reached from any thread: explicitly, from the owner
        # tearing down, or from __del__ whenever the garbage collector happens to
        # run. Without this lock two of them can both find a live handle and
        # destroy the same plugin twice, which corrupts the heap.
        self._destroy_lock = threading.Lock()

        if server_component is None:
            raise ValueError("server_component cannot be None")

        component_handle = server_component._handle

        if not component_handle:
            raise ValueError("server_component handle is null")

        self._handle = self._lib.mavsdk_component_metadata_server_create(
            component_handle
        )

        if not self._handle:
            raise RuntimeError(
                "Failed to create ComponentMetadataServer plugin - C function returned null handle"
            )

        server_component._track_plugin(self)

    def set_metadata(self, metadata):
        """Get set_metadata (blocking)"""

        _metadata_array_type = MetadataCStruct * len(metadata)
        _metadata_array = _metadata_array_type()
        for _i, _item in enumerate(metadata):
            _metadata_array[_i] = _item.to_c_struct()
        _metadata_size = len(metadata)

        self._lib.mavsdk_component_metadata_server_set_metadata(
            self._require_handle(),
            _metadata_array,
            _metadata_size,
        )

    def _require_handle(self) -> ctypes.c_void_p:
        """Fail loudly rather than dereferencing a null handle in C.

        The plugin is destroyed together with its owner, which a caller holding on
        to it may not expect, so using it afterwards would otherwise segfault in
        the C wrapper.
        """
        if not self._handle:
            raise RuntimeError(
                "ComponentMetadataServer has been destroyed (its "
                "server component or "
                "Mavsdk was destroyed, or destroy() was called explicitly)"
            )
        return self._handle

    def destroy(self):
        """Destroy the plugin instance. Idempotent and safe from any thread."""
        with self._destroy_lock:
            handle, self._handle = self._handle, None
            # Taken under the same lock as the handle, so an unsubscribe racing
            # this either gets its entry and releases it itself, or finds the
            # plugin already gone. Neither path releases a handle twice.
            _subscriptions = list(self._subscriptions.items())
            self._subscriptions.clear()

        if handle:
            # The C wrapper does not track these, so release them here. unsubscribe()
            # waits for a running callback, so this cannot race one. The snapshot
            # also holds the trampolines until past destroy, so a late callback
            # cannot jump into collected memory.
            for _subscription, (_cb, _unsubscribe) in _subscriptions:
                _unsubscribe(handle, _subscription)

            self._lib.mavsdk_component_metadata_server_destroy(handle)
            self._callbacks.clear()

    def __del__(self):
        self.destroy()


